let sequence=0;
export function shortcutIcon(name){
 if(!drawings[name])return '';
 const id=`shortcut-${sequence++}`,colors=palettes[name];
 const gradient=(key,a,b)=>`<linearGradient id="${id}-${key}" x2=".25" y2="1"><stop stop-color="${a}"/><stop offset="1" stop-color="${b}"/></linearGradient>`;
 return `<svg viewBox="0 0 64 64" width="60" height="60" aria-hidden="true"><defs>${gradient('main',colors[0],colors[1])}${gradient('back',colors[2],colors[3])}</defs><g class="icon-object">${drawings[name].replaceAll('#MAIN',`#${id}-main`).replaceAll('#BACK',`#${id}-back`)}</g></svg>`;
}
